import{_ as i,c as o,o as n,a5 as a}from"./chunks/framework.CUJoMJm2.js";const h=JSON.parse('{"title":"SBRP Conformance Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbrp/conformance.md","filePath":"protocols/sbrp/conformance.md","lastUpdated":0}'),l={name:"protocols/sbrp/conformance.md"};function t(s,e,r,d,c,m){return n(),o("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbrp/conformance.md for this page in Markdown format</div><h1 id="sbrp-conformance-checklist" tabindex="-1">SBRP Conformance Checklist <a class="header-anchor" href="#sbrp-conformance-checklist" aria-label="Permalink to “SBRP Conformance Checklist”">​</a></h1><blockquote><p><strong>Authority</strong>: Supporting (Test specification)<br><strong>Purpose</strong>: Testable invariants and verification checklist for SBRP implementations.</p></blockquote><p>Use this checklist to verify conformance with SBRP. Requirements reference:</p><ul><li><a href="./cryptography-and-wire">cryptography-and-wire.md</a> — crypto primitives and wire format</li><li><a href="./state-machine">state-machine.md</a> — state transitions and control semantics</li><li><a href="./control-codes">control-codes.md</a> — code values</li><li><a href="./authentication">authentication.md</a> — token validation</li></ul><p>Items tagged MUST/SHOULD mirror normative requirements.</p><h2 id="common-crypto-client-daemon" tabindex="-1">Common Crypto (Client + Daemon) <a class="header-anchor" href="#common-crypto-client-daemon" aria-label="Permalink to “Common Crypto (Client + Daemon)”">​</a></h2><ul><li>[ ] MUST use Ed25519 for daemon identity and X25519 for ephemeral key exchange.</li><li>[ ] MUST UTF-8 encode context strings and <code>daemonId</code> (no BOM, no length prefix) before concatenation in signature/transcript payloads.</li><li>[ ] MUST sign handshake payload <code>SHA256(&quot;sbrp-v1-handshake&quot; || daemonId || clientEphemeralPublicKey || daemonEphemeralPublicKey)</code>.</li><li>[ ] MUST compute transcript hash <code>SHA256(&quot;sbrp-v1-transcript&quot; || daemonId || clientEphemeralPublicKey || daemonEphemeralPublicKey || signature)</code> and use it as HKDF-SHA256 salt.</li><li>[ ] MUST set HKDF <code>info</code> to the constant <code>&quot;sbrp-session-keys&quot;</code> and <code>len = 64</code>.</li><li>[ ] MUST derive directional keys <code>clientToDaemon</code> and <code>daemonToClient</code>.</li><li>[ ] MUST build nonce as 12 bytes: 4-byte direction constant + 8-byte big-endian seq.</li><li>[ ] MUST use empty AAD for ChaCha20-Poly1305 encryption.</li><li>[ ] MUST start sequence numbers at 0 and increment per message per direction.</li><li>[ ] MUST reject messages outside the replay window; MUST use bitmap window &gt;= 64 and SHOULD use &gt;= 128.</li><li>[ ] MUST handle large sequence jumps in O(1) by resetting the bitmap rather than iterating.</li><li>[ ] MUST preserve sequence state on resume without handshake; if lost, MUST force full handshake.</li></ul><h2 id="client-ui" tabindex="-1">Client (UI) <a class="header-anchor" href="#client-ui" aria-label="Permalink to “Client (UI)”">​</a></h2><ul><li>[ ] MUST pin daemon identity public key on first successful handshake (TOFU); do not pin before signature verification succeeds.</li><li>[ ] MUST persist pins across page reloads (for browser clients); SHOULD survive application restarts.</li><li>[ ] MUST abort on identity mismatch with <code>identity_key_changed</code> and require explicit user approval to accept new key.</li><li>[ ] MUST present both stored and new fingerprints on <code>identity_key_changed</code>.</li><li>[ ] MUST verify daemon signature using pinned identity key, not relay-provided key.</li><li>[ ] MUST obtain a new session token (new <code>sid</code>) on client reconnect; no session resumption.</li><li>[ ] MUST perform a full handshake on client reconnect (new ephemeral keys).</li><li>[ ] MUST handle <code>Control(session_paused)</code> by suspending encrypted sends.</li><li>[ ] MUST handle <code>Control(session_pending)</code> to indicate daemon reconnected, awaiting readiness.</li><li>[ ] MUST handle <code>Control(session_resumed)</code> by resuming with retained session state.</li><li>[ ] MUST handle <code>Control(session_expired)</code> by initiating full reconnect with new handshake.</li><li>[ ] SHOULD complete handshake within 30 seconds of WebSocket open; MUST abort with <code>handshake_failed</code> on timeout.</li><li>[ ] SHOULD warn when storage is unavailable or ephemeral (private/incognito).</li><li>[ ] MUST NOT parse Control message text for behavioral decisions; use only the code.</li></ul><h2 id="daemon-agent" tabindex="-1">Daemon (Agent) <a class="header-anchor" href="#daemon-agent" aria-label="Permalink to “Daemon (Agent)”">​</a></h2><ul><li>[ ] MUST generate and persist a long-lived Ed25519 identity keypair; register public key with control plane.</li><li>[ ] MUST sign its ephemeral X25519 public key in <code>HandshakeAccept</code>.</li><li>[ ] MUST sign with the identity key currently registered as active at the control plane.</li><li>[ ] MUST maintain per-client session state (keys, seq, replay window) independently.</li><li>[ ] MUST handle <code>Control(session_ended)</code> by cleaning up per-session state (keys, seq counters, replay window).</li><li>[ ] SHOULD complete handshake within 30 seconds of receiving <code>HandshakeInit</code>; MUST abort with <code>handshake_failed</code> on timeout.</li><li>[ ] SHOULD store identity keys with restrictive permissions (e.g., 0600).</li><li>[ ] SHOULD best-effort zeroize ephemeral key material after use.</li></ul><h3 id="session-resumption-resumable-daemons-only" tabindex="-1">Session Resumption (resumable daemons only) <a class="header-anchor" href="#session-resumption-resumable-daemons-only" aria-label="Permalink to “Session Resumption (resumable daemons only)”">​</a></h3><p>Daemons with <code>res: false</code> in their presence token skip this section—the relay handles session cleanup automatically on reconnect.</p><ul><li>[ ] MUST resume with the same keys and sequence state if relay session is resumed.</li><li>[ ] MUST send <code>Signal(ready)</code> for sessions with retained state after reconnect.</li><li>[ ] MUST verify session state integrity before sending <code>Signal(ready)</code>; if any component is missing, malformed, or inconsistent, MUST send <code>Signal(close, reason=state_lost)</code> instead.</li><li>[ ] MUST send <code>Signal(close)</code> for all sessions after process restart or loss of volatile memory.</li></ul><h3 id="signal-frame-requirements" tabindex="-1">Signal Frame Requirements <a class="header-anchor" href="#signal-frame-requirements" aria-label="Permalink to “Signal Frame Requirements”">​</a></h3><ul><li>[ ] MUST use 2-byte payload: signal code (1B) + reason code (1B).</li><li>[ ] MUST use signal code <code>0x00</code> for ready, <code>0x01</code> for close.</li><li>[ ] SHOULD use reason code <code>0x00</code> (<code>none</code>) for ready signal.</li><li>[ ] MUST use appropriate reason code for close: <code>0x00</code> none, <code>0x01</code> state_lost, <code>0x02</code> shutdown, <code>0x03</code> policy, <code>0x04</code> error.</li></ul><h2 id="relay" tabindex="-1">Relay <a class="header-anchor" href="#relay" aria-label="Permalink to “Relay”">​</a></h2><ul><li>[ ] MUST validate relay tokens issued by the control plane (not authenticate directly).</li><li>[ ] MUST enforce token claims: role, daemonId, expiration; sessionId required for client tokens only.</li><li>[ ] MUST enforce user → daemon ownership via token claims.</li><li>[ ] MUST forward endpoint frames (<code>0x01</code>, <code>0x02</code>, <code>0x03</code>) without modification or inspection.</li><li>[ ] MUST handle <code>Signal(ready)</code> from daemon: send <code>Control(session_resumed)</code> to client, resume routing.</li><li>[ ] MUST handle <code>Signal(close)</code> from daemon: send <code>Control(session_expired)</code> to client, close session pairing.</li><li>[ ] MUST reject <code>Signal</code> (<code>0x04</code>) received from clients as <code>disallowed_sender</code> if header is parseable.</li><li>[ ] MUST reject <code>Control</code> (<code>0x20</code>) received from peers as <code>disallowed_sender</code> if header is parseable.</li><li>[ ] MUST close WebSocket with <code>Control(malformed_frame, SessionID=0)</code> if frame header is malformed or truncated.</li><li>[ ] MUST rate-limit connections and message throughput per §8.6.</li><li>[ ] MUST send <code>Control(session_paused)</code> to client when daemon disconnects.</li><li>[ ] MUST send <code>Control(session_pending)</code> to client when resumable daemon reconnects within grace period.</li><li>[ ] MUST NOT send <code>Control(session_resumed)</code> until receiving <code>Signal(ready)</code> from daemon (resumable daemons only).</li><li>[ ] MUST send <code>Control(session_expired)</code> to client and close WebSocket when grace window expires.</li><li>[ ] MUST send <code>Control(session_ended)</code> to daemon when client disconnects, if daemon is connected; silently tear down pairing if daemon is offline.</li><li>[ ] MUST validate JWT tokens: issuer, audience (<code>sideband-relay</code>), expiration, and role/daemon/client claims per Appendix C.</li><li>[ ] MUST verify <code>sid</code> in token (base64url-decoded to uint64) matches frame header SessionID for client connections.</li><li>[ ] MUST NOT generate Control frames that leak information derived from encrypted payloads.</li><li>[ ] MUST NOT include identifiers (daemonId, clientId, sessionId, tokens) in Control message text.</li><li>[ ] MUST send <code>Control(session_expired)</code> to all paired clients immediately when non-resumable daemon (<code>res: false</code>) reconnects.</li><li>[ ] SHOULD send <code>Control(internal_error, SessionID=0)</code> and close WebSocket on unrecoverable internal failures.</li></ul><h3 id="frame-validation-order" tabindex="-1">Frame Validation Order <a class="header-anchor" href="#frame-validation-order" aria-label="Permalink to “Frame Validation Order”">​</a></h3><ul><li>[ ] MUST validate frames in order per §13.3: header parse → payload size → frame type → SessionID validity → frame direction.</li><li>[ ] MUST use <code>invalid_session_id</code> (SID=0) if session-bound frame has SessionID=0 or Ping/Pong has non-zero SessionID.</li><li>[ ] MUST use <code>disallowed_sender</code> with header&#39;s SessionID only after SessionID validity passes.</li><li>[ ] MUST use <code>rate_limited</code> with SID=0 (connection-level per §8.6).</li></ul><h3 id="keepalive-ping-pong" tabindex="-1">Keepalive (Ping/Pong) <a class="header-anchor" href="#keepalive-ping-pong" aria-label="Permalink to “Keepalive (Ping/Pong)”">​</a></h3><ul><li>[ ] MUST handle Ping (<code>0x10</code>) locally: respond with Pong (<code>0x11</code>) copying payload.</li><li>[ ] MUST NOT forward Ping or Pong frames.</li><li>[ ] Ping/Pong frames MUST have SessionID = 0 (connection-scoped).</li><li>[ ] Ping payload MUST be 0-8 bytes; relay MUST reject larger payloads.</li><li>[ ] MAY send Ping to endpoints to detect dead connections.</li></ul><h2 id="control-code-compliance" tabindex="-1">Control Code Compliance <a class="header-anchor" href="#control-code-compliance" aria-label="Permalink to “Control Code Compliance”">​</a></h2><h3 id="wire-codes-relay-→-endpoint" tabindex="-1">Wire Codes (Relay → Endpoint) <a class="header-anchor" href="#wire-codes-relay-→-endpoint" aria-label="Permalink to “Wire Codes (Relay → Endpoint)”">​</a></h3><ul><li>[ ] MUST use code ranges per §14.1: 0x01xx auth, 0x02xx routing, 0x03xx session, 0x04xx wire, 0x06xx internal, 0x09xx rate, 0x10xx state.</li><li>[ ] MUST use correct SessionID scope per §14.1 SID column: 0 for connection-level errors, non-zero for session-specific events.</li><li>[ ] Terminal codes (T in §14.1) MUST close WebSocket after sending.</li><li>[ ] Non-terminal codes (N in §14.1) MUST NOT close WebSocket.</li></ul><h3 id="endpoint-codes-sdk-only" tabindex="-1">Endpoint Codes (SDK Only) <a class="header-anchor" href="#endpoint-codes-sdk-only" aria-label="Permalink to “Endpoint Codes (SDK Only)”">​</a></h3><ul><li>[ ] MUST use 0xExxx range for SDK-only codes (never transmitted on wire).</li><li>[ ] <code>identity_key_changed</code> (0xE001) MUST trigger abort and user confirmation flow.</li><li>[ ] <code>handshake_failed</code> (0xE002) MUST trigger connection close.</li><li>[ ] <code>handshake_timeout</code> (0xE003) MUST trigger connection close after 30s.</li><li>[ ] <code>decrypt_failed</code> (0xE004) MUST trigger connection close.</li><li>[ ] <code>sequence_error</code> (0xE005) MUST reject message; MAY trigger connection close.</li></ul><h2 id="optional-quick-connect-control-plane" tabindex="-1">Optional: Quick Connect (Control Plane) <a class="header-anchor" href="#optional-quick-connect-control-plane" aria-label="Permalink to “Optional: Quick Connect (Control Plane)”">​</a></h2><ul><li>[ ] MUST be disabled by default; require explicit operator opt-in for production deployments.</li><li>[ ] MUST issue time-limited codes (≤5 minutes) and enforce expiry server-side.</li><li>[ ] MUST rate-limit code generation (e.g., max 10 per minute per daemon).</li><li>[ ] MUST enforce TTL eviction; SHOULD enforce one-time use; MAY use durable storage with TTL for HA.</li><li>[ ] MUST issue standard relay session token after code validation; relay sees no difference.</li><li>[ ] Client MUST perform normal E2EE handshake with signature verification.</li><li>[ ] SHOULD warn that Quick Connect provides reduced authentication guarantees.</li></ul>',30)])])}const u=i(l,[["render",t]]);export{h as __pageData,u as default};
